from __future__ import annotations

from ..template_inventory import TemplateInventory
from ..template_runtime import TemplateRuntime
from ..vars_contracts import VarsSchema


class TemplateDocsGenerator:
    """Builds Markdown reference docs for repo-local template APIs."""

    def functions_markdown(
        self, *, runtime: TemplateRuntime, inventory: TemplateInventory
    ) -> str:
        lines = [
            "# BKKT Functions",
            "",
            "Autogenerated reference for `${fn:...}` functions available in this repo.",
            "",
            "| Function | Source | Used by manifests | Description |",
            "|---|---|---:|---|",
        ]
        for item in runtime.list_functions():
            used = len(inventory.used_by_function(item.name))
            source = str(item.source_path) if item.source_path else item.source
            lines.append(
                "| "
                + " | ".join(
                    [
                        f"`{_escape(item.name)}`",
                        _escape(source),
                        str(used),
                        _escape(item.description.strip() or "-"),
                    ]
                )
                + " |"
            )
        lines.extend(
            [
                "",
                "Generated by `bkkt functions docs generate`.",
                "",
            ]
        )
        return "\n".join(lines)

    def vars_markdown(self, *, schema: VarsSchema, inventory: TemplateInventory) -> str:
        lines = [
            "# BKKT Variables",
            "",
            "Autogenerated reference for repo variables declared in `bkkt/vars.schema.yaml`.",
            "",
            "| Variable | Type | Required | Sensitive | Used by manifests | Description |",
            "|---|---|---:|---:|---:|---|",
        ]
        for entry in sorted(schema.entries, key=lambda item: item.key):
            used = len(inventory.used_by_variable(entry.key))
            lines.append(
                "| "
                + " | ".join(
                    [
                        f"`{_escape(entry.key)}`",
                        entry.type,
                        "yes" if entry.required else "no",
                        "yes" if entry.sensitive else "no",
                        str(used),
                        _escape(entry.description or "-"),
                    ]
                )
                + " |"
            )
        if not schema.entries:
            lines.append("| _No schema entries found_ | - | - | - | - | - |")
        lines.extend(
            [
                "",
                "Generated by `bkkt vars docs generate`.",
                "",
            ]
        )
        return "\n".join(lines)


def _escape(value: str) -> str:
    return value.replace("|", "\\|").replace("\n", " ")
